Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$Repo = 'D:\IIP_Obsidian_Integration_v1.0\iip_obsidian_integration_v1'
$V = Join-Path $Repo 'reports\PCIP11_EVIDENCE_VALIDATION_0695_5R2.csv'
$C = Join-Path $Repo 'reports\PCIP11_METRIC_EVIDENCE_CANDIDATES_0695_4.csv'
$O = Join-Path $Repo 'reports'
$Out = Join-Path $O 'PCIP11_STRUCTURED_EVIDENCE_0695_6R2.csv'
$Cand = Join-Path $O 'PCIP11_METRIC_PROMOTION_CANDIDATES_0695_6R2.csv'
$Hold = Join-Path $O 'PCIP11_STRUCTURED_EVIDENCE_0695_6R2_HOLD.csv'
function S($x){ if($null -eq $x){''} else {[string]$x.Trim()} }
function N($x){ if([string]::IsNullOrWhiteSpace($x)){return $null}; $s=$x.Trim() -replace '\.','' -replace ',','.'; $n=0.0; if([double]::TryParse($s,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$n)){return $n}; return $null }
function Period($p){ if((S $p) -match 'MONTH:(20\d{2}-\d{2})'){return $Matches[1]}; if((S $p) -match 'QUARTER:(20\d{2}-T[1-4])'){return $Matches[1]}; if((S $p) -match 'YEAR:(20\d{2})'){return $Matches[1]}; return '' }
if(!(Test-Path $V)){throw "Missing: $V"}; if(!(Test-Path $C)){throw "Missing: $C"}
Write-Host ''; Write-Host '============================================================'; Write-Host '0695.6R2 - PCIP11 STRUCTURED EVIDENCE EXTRACTION'; Write-Host '============================================================'; Write-Host ''
Write-Host '[1/8] Loading inputs...'; $vr=@(Import-Csv $V); $cr=@(Import-Csv $C); Write-Host ("Validation rows: {0}" -f $vr.Count); Write-Host ("Candidate rows: {0}" -f $cr.Count)
Write-Host '[2/8] Selecting validated rows using 0695.5R2 Validation_Class...'; $ready=@($vr|Where-Object{(S $_.Validation_Class) -like '*_EVIDENCE_READY_REVIEW'}); Write-Host ("Evidence-ready rows: {0}" -f $ready.Count); if($ready.Count -ne 119){Write-Host 'WARNING: expected 119 rows.'}
if($ready.Count -eq 0){$vr|Group-Object Validation_Class|Sort-Object Count -Descending|%{Write-Host("  {0} = {1}" -f $_.Name,$_.Count)}; throw 'No validated rows selected.'}
Write-Host '[3/8] Joining to 0695.4 by SHA256...'; $map=@{}; foreach($r in $cr){$h=S $r.SHA256;if($h){$map[$h]=$r}}; $j=@(); $miss=0; foreach($r in $ready){$h=S $r.SHA256;if($map.ContainsKey($h)){$j += [pscustomobject]@{V=$r;C=$map[$h]}}else{$miss++}}; Write-Host ("Joined: {0}" -f $j.Count); Write-Host ("Join misses: {0}" -f $miss); if($j.Count -eq 0){throw 'No SHA256 joins.'}
Write-Host '[4/8] Extracting semantic candidates...'; $rows=New-Object System.Collections.Generic.List[object]
function AddR($x,$cat,$metric,$val,$unit,$method,$note,$ev){$rows.Add([pscustomobject][ordered]@{Historical_ID=S $x.V.Historical_ID;SHA256=S $x.V.SHA256;FileName=S $x.C.FileName;RelativePath=S $x.C.RelativePath;Identity_Class=S $x.V.Identity_Class;Document_Role=S $x.V.Document_Role;Content_Periods=S $x.C.Content_Periods;Period_Quality=S $x.V.Period_Quality;Validation_Class=S $x.V.Validation_Class;Metric=$metric;Value=$val;Unit=$unit;Period=(Period $x.C.Content_Periods);Category=$cat;Status='PROMOTION_CANDIDATE_REVIEW';Promotion_Action='DO_NOT_PROMOTE_YET';Extraction_Method=$method;Evidence_Text=($ev -replace '\s+',' ');Notes=$note})}
foreach($x in $j){foreach($q in @(@('DISTRIBUTION','Distribution_Evidence'),@('NAV_PL','NAV_PL_Evidence'),@('RESULT','Result_Evidence'),@('PORTFOLIO_CREDIT','Portfolio_Credit_Evidence'),@('EVENT','Event_Evidence'))){$cat=$q[0];$ev=S $x.C.($q[1]);if(!$ev){continue};$t=$ev -replace '\s+',' '
  $m=[regex]::Match($t,'(?i)(?:foi\s+)?distribu[ií]d[oa].{0,100}?R\$\s*([0-9]+(?:[,.][0-9]+)?)\s*/\s*cota');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'distribution_per_share' $n 'BRL/share' 'semantic_anchor' 'Verify exact date/table context' $t}}
  $m=[regex]::Match($t,'(?i)rendimento\s+distribu[ií]do\s*\(R\$/cota\).{0,120}?([0-9]+(?:[,.][0-9]+)?)');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'distribution_per_share' $n 'BRL/share' 'semantic_anchor' 'Verify column/header' $t}}
  $m=[regex]::Match($t,'(?i)Dividend\s+Yield\s+anualizado.{0,70}?([0-9]+(?:[,.][0-9]+)?)\s*%');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'dividend_yield_annualized' $n 'percent' 'semantic_anchor' 'Verify reference price/date' $t}}
  $m=[regex]::Match($t,'(?i)Patrim[oô]nio\s+L[ií]quido.{0,100}?R\$\s*([0-9]+(?:[.,][0-9]+)?)\s*/\s*cota');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'net_asset_value_per_share' $n 'BRL/share' 'semantic_anchor' 'Explicit PL per share' $t}}
  $m=[regex]::Match($t,'(?i)Valor\s+de\s+Mercado.{0,120}?R\$\s*([0-9]+(?:[.,][0-9]+)?)\s*/\s*cota');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'market_price_per_share' $n 'BRL/share' 'semantic_anchor' 'Explicit market value per share' $t}}
  $m=[regex]::Match($t,'(?i)(?:Price\s+to\s+book|P/?B).{0,40}?([0-9]+(?:[.,][0-9]+)?)\s*x');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'price_to_book' $n 'ratio' 'semantic_anchor' 'Explicit P/B' $t}}
  foreach($rr in @(@('total_revenue','(?:Receita|Receitas)\s*[-–]\s*Total'),@('operating_result','Resultado\s+Operacional'),@('financial_result','Resultado\s+Financeiro\s+L[ií]quido'),@('accounting_net_income','Lucro\s+L[ií]quido\s+Cont[aá]bil'),@('distributable_net_income','Lucro\s+L[ií]quido\s+Distribu[ií]vel'),@('expenses_total','Despesas\s*[-–]\s*Total'))){$m=[regex]::Match($t,"(?i)$($rr[1])\s+(-?\(?[0-9]+(?:[.,][0-9]+)?)\)?");if($m.Success){$raw=$m.Groups[1].Value;$neg=$raw.StartsWith('(');$n=N ($raw -replace '[()]','');if($null -ne $n -and $neg){$n=-$n};if($null -ne $n){AddR $x $cat $rr[0] $n 'table_value_pending_unit_scale' 'semantic_anchor' 'Verify million/thousand/per-share scale and column' $t}}}
  $m=[regex]::Match($t,'(?i)LTV\s+m[eé]dio.{0,25}?([0-9]+(?:[,.][0-9]+)?)\s*%');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'ltv_average' $n 'percent' 'semantic_anchor' 'Explicit LTV' $t}}
  $m=[regex]::Match($t,'(?i)prazo\s+m[eé]dio.{0,40}?([0-9]+(?:[,.][0-9]+)?)\s*anos');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'weighted_average_term_years' $n 'years' 'semantic_anchor' 'Explicit average term' $t}}
  $m=[regex]::Match($t,'(?i)spread\s+m[eé]dio.{0,40}?([0-9]+(?:[,.][0-9]+)?)\s*%');if($m.Success){$n=N $m.Groups[1].Value;if($null -ne $n){AddR $x $cat 'weighted_average_spread' $n 'percent' 'semantic_anchor' 'Explicit average spread' $t}}
}}
$uniq=@{};$outRows=New-Object System.Collections.Generic.List[object];foreach($r in $rows){$k='{0}|{1}|{2}|{3}|{4}|{5}' -f $r.SHA256,$r.Category,$r.Metric,$r.Value,$r.Unit,$r.Period;if(!$uniq.ContainsKey($k)){$uniq[$k]=$true;$outRows.Add($r)}};Write-Host ("Structured metric rows: {0}" -f $outRows.Count)
Write-Host '[5/8] Preserving unmatched evidence as HOLD...';$matched=@{};foreach($r in $outRows){$matched[$r.SHA256]=$true};$holds=New-Object System.Collections.Generic.List[object];foreach($x in $j){if(!$matched.ContainsKey($x.C.SHA256)){foreach($q in @(@('DISTRIBUTION','Distribution_Evidence'),@('NAV_PL','NAV_PL_Evidence'),@('RESULT','Result_Evidence'),@('PORTFOLIO_CREDIT','Portfolio_Credit_Evidence'),@('EVENT','Event_Evidence'))){$ev=S $x.C.($q[1]);if($ev){AddR $x $q[0] 'UNSTRUCTURED_EVIDENCE' '' 'text' 'preserve_block' 'Manual semantic review required' $ev;$holds.Add($rows[$rows.Count-1])}}}};Write-Host ("HOLD rows: {0}" -f $holds.Count)
Write-Host '[6/8] Saving CSV outputs...';New-Item -ItemType Directory -Force -Path $O|Out-Null;$outRows|Export-Csv $Out -NoTypeInformation -Encoding UTF8;$holds|Export-Csv $Hold -NoTypeInformation -Encoding UTF8;$outRows|Select-Object Historical_ID,SHA256,FileName,RelativePath,Identity_Class,Document_Role,Metric,Value,Unit,Period,Category,Status,Promotion_Action,Evidence_Text,Notes|Export-Csv $Cand -NoTypeInformation -Encoding UTF8
Write-Host '[7/8] Final controls...';if(!(Test-Path $Out)){throw 'Structured output missing'};if(!(Test-Path $Cand)){throw 'Candidate output missing'}
Write-Host '[8/8] REPORT';Write-Host '';Write-Host ("0695.5R2 validated      : {0}" -f $ready.Count);Write-Host ("SHA256 joined           : {0}" -f $j.Count);Write-Host ("Join misses             : {0}" -f $miss);Write-Host ("Structured metric rows  : {0}" -f $outRows.Count);Write-Host ("HOLD/unstructured       : {0}" -f $holds.Count);Write-Host '';Write-Host 'CONTROL: NO VAULT CHANGE / NO METRIC PROMOTION';Write-Host '';Write-Host "CSV : $Out";Write-Host "CSV : $Cand";Write-Host "CSV : $Hold";Write-Host '============================================================'
